import{_ as r}from"./chunks/printers.D1gLuFrs.js";import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.DSc8fo6x.js";const q=JSON.parse('{"title":"Çek və etiket printeri","description":"","frontmatter":{},"headers":[],"relativePath":"printerler.md","filePath":"printerler.md"}'),l={name:"printerler.md"};function o(s,t,d,u,p,b){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="cek-və-etiket-printeri" tabindex="-1">Çek və etiket printeri <a class="header-anchor" href="#cek-və-etiket-printeri" aria-label="Permalink to &quot;Çek və etiket printeri&quot;">​</a></h1><p>Bir termal printer (məs. <strong>Xprinter XP-365B</strong>) həm qəbz, həm barkod etiketi çap edə bilər.</p><h2 id="qosmaq" tabindex="-1">Qoşmaq <a class="header-anchor" href="#qosmaq" aria-label="Permalink to &quot;Qoşmaq&quot;">​</a></h2><ol><li>Printeri USB ilə qoşun və onun <strong>Windows drayverini</strong> quraşdırın (qutudakı disk və ya istehsalçının saytı). Windows-un &quot;Printerlər&quot; siyahısında görünməlidir.</li><li>Kassa → <strong>Ayarlar → Printerlər</strong>: <ul><li><strong>Qəbz printeri</strong> və <strong>Etiket (barkod) printeri</strong> — siyahıdan cihazı seçin (eyni cihaz ola bilər);</li><li><strong>Etiket ölçüsü</strong> (Satış və çap kartında) — rulondakı etiketin ölçüsü (məs. 40×30);</li><li>istəsəniz: <strong>Satış bitəndə qəbz özü çap olunsun</strong>, <strong>Nağd satışda kassa qutusunu aç</strong>.</li></ul></li><li><strong>Yadda saxla</strong> → <strong>Sınaq qəbzi</strong> və <strong>Sınaq etiketi</strong>.</li><li>Sınaq etiketinin barkodunu skanerlə oxudun — &quot;bip&quot; olmalıdır.</li></ol><p><img src="'+r+'" alt="Printerlər"></p><h2 id="necə-isləyir" tabindex="-1">Necə işləyir <a class="header-anchor" href="#necə-isləyir" aria-label="Permalink to &quot;Necə işləyir&quot;">​</a></h2><ul><li>Printer seçilibsə — qəbz və etiket <strong>pəncərəsiz, birbaşa</strong> gedir.</li><li>Printer seçilməyibsə (&quot;Çap pəncərəsi&quot;) — hər çapda Windows-un çap pəncərəsi açılır, istənilən printerlə işləyir.</li><li>Printer sönülüdürsə və ya kağız bitibsə — xəta çıxır və <strong>&quot;Çap pəncərəsi ilə&quot;</strong> təklif olunur. Qəbz itmir.</li></ul><h2 id="problemler" tabindex="-1">Problemlər <a class="header-anchor" href="#problemler" aria-label="Permalink to &quot;Problemlər {#problemler}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simptom</th><th>Nə etmək</th></tr></thead><tbody><tr><td>&quot;Seçilmiş printer tapılmadı&quot;</td><td>Printer qoşulub və yanılıdır? Ayarlarda yenidən seçin.</td></tr><tr><td>Etiket iki etiketə bölünür / boşluq qalır</td><td>&quot;Etiket ölçüsü&quot; rulonla eyni olmalıdır. Printerin sensorunu kalibrləyin (Xprinter: FEED düyməsini basılı saxlayıb yandırın).</td></tr><tr><td>Barkod oxunmur</td><td>Termal başlığı təmizləyin; 30×20 etiketdə barkod kiçikdir — 40×30 daha yaxşıdır.</td></tr><tr><td>Kassa qutusu açılmır</td><td>Qutu qəbz printerinin RJ11 yuvasına qoşulmalıdır (bəzi etiket printerlərində bu yuva yoxdur). &quot;Qutunu aç&quot; sınağına baxın.</td></tr></tbody></table>',9)])])}const h=i(l,[["render",o]]);export{q as __pageData,h as default};
